const steps = Array.from(document.querySelectorAll('nys-step'));
const stepContent = document.getElementById('step-content');
const nextButton = document.getElementById('next-step');

// `current` marks the furthest step reached, and `selected` marks the step on
// screen. Steps marked `previous` sit before `current` and are navigable.
const currentIndex = () => steps.findIndex((step) => step.current);
function selectedIndex() {
  const index = steps.findIndex((step) => step.selected);
  return index === -1 ? currentIndex() : index;
}

function showStep(index) {
  steps.forEach((step, i) => {
    step.selected = i === index;
  });
  const current = currentIndex();
  const label = steps[index].label;
  stepContent.textContent =
    index === current
      ? `You are on step ${index + 1} of ${steps.length}: ${label}.`
      : `You are reviewing step ${index + 1} of ${steps.length}: ${label}. Your progress stays at step ${current + 1}.`;
  nextButton.disabled = index === steps.length - 1;
}

nextButton.addEventListener('nys-click', () => {
  const next = selectedIndex() + 1;
  if (next >= steps.length) return;
  if (next > currentIndex()) {
    steps[currentIndex()].current = false;
    steps[next].current = true;
    // Workaround for an NYSDS 1.23.1 bug: when `current` moves to a later step,
    // nys-stepper doesn't add `previous` to the steps before it, so they can't
    // be selected and never fire nys-step-click. NYSDS issue: not filed yet.
    steps.forEach((step, i) => step.toggleAttribute('previous', i < next));
  }
  showStep(next);
});

// Earlier steps fire nys-step-click. Steps after `current` never do.
steps.forEach((step, index) => {
  step.addEventListener('nys-step-click', () => showStep(index));
});
